const audits = $('1. UCP/ACP Store Readiness Audit (/v1/store-readiness)').all();
const leads = $input.all();
const reports = [];
for (let i = 0; i < leads.length; i++) {
  const a = (audits[i] && audits[i].json) || {};
  const l = (leads[i] && leads[i].json) || {};
  const disc = a.discovery || {};
  const ucpValid = Boolean(disc['/.well-known/ucp'] && disc['/.well-known/ucp'].valid);
  const acpValid = Boolean(disc['/.well-known/acp/config.json'] && disc['/.well-known/acp/config.json'].valid);
  const contacts = l.public_contacts || {};
  reports.push({
    json: {
      domain: a.domain || l.domain,
      readiness_score: a.readiness_score ?? 0,
      ucp_endpoint_valid: ucpValid,
      acp_endpoint_valid: acpValid,
      active_ad_spend_verified: Boolean(l.active_ad_spend_verified),
      recommended_fixes: (a.fixes || []).join(' | '),
      emails: (contacts.emails || []).join(', '),
      social_links: (contacts.social_links || []).join(', '),
      agency_pitch_hook: `Your store (${a.domain || l.domain}) scores ${a.readiness_score ?? 0}/100 on AI Shopping Agent Readiness (UCP: ${ucpValid ? 'OK' : 'MISSING'}, ACP: ${acpValid ? 'OK' : 'MISSING'}). Top fixes: ${(a.fixes || []).slice(0, 2).join('; ')}`
    }
  });
}
return reports;
